window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:obstetricia-partograma-e-distocia"]={"block":"anki:obstetricia-partograma-e-distocia","label":"Anki · Partograma e Distocia","count":84,"questions":[{"id":"anki-obstetricia-partograma-e-distocia-fcf3f72720cae988","number":"0301l","sourceNumber":"0301l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Uma gestante dá entrada na maternidade em trabalho de parto. Ao toque colo dilatado 4 cm, bolsa rota, apresentação cefálica. Aberto o partograma de Friedmann, o Obstetra deve traçar a linha de ação:","options":{"A":"2 horas após a linha de alerta.","B":"2 horas antes da linha de alerta.","C":"4 horas após a linha de alerta.","D":"4 horas antes da linha de alerta."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860729","ankiGuid":"I`kpkft93("},{"id":"anki-obstetricia-partograma-e-distocia-d02b2a6de0f77067","number":"0302l","sourceNumber":"0302l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Paciente G3 PV2 é admitida em pronto atendimento obstétrico em trabalho de parto espontâneo com 38 semanas e 6 dias. Ao verificar o partograma, o plantonista constata que essa se encontra em período expulsivo há 3 horas, sem raquianestesia. Ao examinar verifica-se colo dilatado 10cm, feto cefálico em OP e plano +2 de De Lee. Assinale a alternativa que apresenta o diagnóstico e a conduta MAIS apropriada para essa paciente:","options":{"A":"Parada secundária da descida e estimular verticalização.","B":"Parada secundária da dilatação e prescrever ocitócito.","C":"Período expulsivo prolongado e propor parto vaginal operatório.","D":"Período expulsivo adequado e manter acompanhamento do trabalho de parto."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860731","ankiGuid":"q!(aA{NKCO"},{"id":"anki-obstetricia-partograma-e-distocia-a08f2d0603257cfc","number":"0303l","sourceNumber":"0303l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Uma mulher de 24 anos de idade, G2P0A1, no decorrer de 41 semanas de gestação, encontrase em fase ativa do trabalho de parto, está fazendo força, mas sem progresso. O desenvolvimento do trabalho de parto está caracterizado no partograma abaixo.\n\nA análise adequada do caso clínico é:","options":{"A":"O partograma demonstra período pélvico prolongado, pois a descida da apresentação é progressiva, mas excessivamente lenta.","B":"A evolução do trabalho de parto é normal, pois a paciente foi submetida à analgesia peridural.","C":"O partograma evidencia evolução anormal do trabalho de parto. A causa mais frequente desse tipo de distocia é a desproporção céfalopélvica.","D":"Houve uma parada secundária da dilatação e deverá ser aplicado um fórcipe de Simpson para ultimação do parto."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-740c044b04f3c3dbe139a41100934024b7d4afd1.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860732","ankiGuid":"jTp$>uI-iA"},{"id":"anki-obstetricia-partograma-e-distocia-a1c6fd73512af623","number":"0304l","sourceNumber":"0304l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Você está acompanhando uma paciente secundigesta, com 1 parto normal prévio, em trabalho de parto. Após 6 horas de evolução, você identifica no partograma uma distócia por hipoatividade uterina. Nesta situação e considerando-se o partograma, qual é a conduta imediata mais indicada?","options":{"A":"Cesárea.","B":"Expectante.","C":"Analgesia.","D":"Ocitocina via oral.","E":"Ocitocina endovenosa."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860733","ankiGuid":"zjU.{SSGX0"},{"id":"anki-obstetricia-partograma-e-distocia-1431869e9a8f736d","number":"0305l","sourceNumber":"0305l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Primigesta, gestação de risco usual, com a evolução do trabalho de parto demonstrada no partograma abaixo.\n\nAssinale a alternativa que contém o tipo de distócia apresentada e a conduta obstétrica:","options":{"A":"Parada secundária da descida e fórceps de rotação","B":"Parada secundária da descida e operação cesariana","C":"Fase ativa protraída e infusão intravenosa de ocitocina","D":"Desproporção cefalopélvica relativa e infusão intravenosa de ocitocina"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-998c3d9966d77cac7d75dd0537c290020e5d6b10.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860734","ankiGuid":"jBqv<(6$q;"},{"id":"anki-obstetricia-partograma-e-distocia-ff10cc5f00280f78","number":"0307l","sourceNumber":"0307l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Primigesta, 32 anis, 41 semanas de gestação de risco habitual. Interna na fase ativa da dilatação para assistência ao parto. Na admissão apresentava sinais vitais e exame físico geral normal, altura uterina=38 cm, vitalidade fetal normal. A evolução gráfica de seu trabalho de parto está representada abaixo (Figura).\n\nQual é a conduta para após a avaliação das 20h?","options":{"A":"Aguardar mais uma hora de período expulsivo.","B":"Realizar parto instrumentalizado.","C":"Realizar amniotomia artificial.","D":"Estimular a paciente a realizar puxos dirigidos."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-ecc5af364f1204d7508be5f05a58d489b7bc2bb7.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860736","ankiGuid":"uFe+Gg.R{x"},{"id":"anki-obstetricia-partograma-e-distocia-b27179184a724f2d","number":"0308l","sourceNumber":"0308l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Uma primigesta, cardiopata por doença reumática, classe funcional NYHA I, com boa evolução do trabalho de parto, apresenta parada na progressão. A apresentação é occipito direita transversa e com assinclitismo anterior, plano +2 de DeLee. Os batimentos cardíacos fetais estão em 128bpm. Considerando o quadro clínico apresentado, a melhor conduta no momento seria:","options":{"A":"Cesariana de emergência.","B":"Fórcipe de Simpson.","C":"Fórcipe de Kielland.","D":"Fórcipe de Piper.","E":"Aguardar a evolução do parto."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860737","ankiGuid":"zN3FQ_/R2J"},{"id":"anki-obstetricia-partograma-e-distocia-771c206259640331","number":"0309l","sourceNumber":"0309l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Distocia é por definição a anormalidade no desenrolar do trabalho de parto, sendo apontada nos Estados Unidos como a indicação mais comum de cesárea em primigestas. Em relação à distocia analise as alternativas abaixo. I - A principal complicação associada ao diagnóstico de distocia é infecção, sobretudo a corioamnionite e suas conseqüências para o feto e para a mãe, e está diretamente relacionada à duração do trabalho de parto. II - Define-se distocia funcional como a presença de anormalidade do fator contrátil durante o trabalho de parto, o que infuencia diretamente a progressão da dilatação cervical. III - A distocia por hiperatividade sem obstrução é comum em primiparas e caracteriza-se pela evolução rápida (menos que 3 horas) do trabalho de parto. É conhecida como parto taquitócico. Sobre esta situação selecione a opção correta.","options":{"A":"As afirmativas I e II são verdadeiras. A afirmativa III é falsa.","B":"As afirmativas I e III são verdadeiras. A afirmativa II é falsa.","C":"As afirmativas II e III são verdadeiras. A afirmativa I é falsa.","D":"As afirmativas I, II e III são verdadeiras.","E":"As afirmativas I, II e III são falsas."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860738","ankiGuid":"DJ-:/H4nz,"},{"id":"anki-obstetricia-partograma-e-distocia-62164339f3d57d95","number":"0310l","sourceNumber":"0310l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Partograma é um gráfico no qual são anotadas a progressão do trabalho de parto e as condições da mãe e as do feto. Quando bem utilizado, ele permite diminuição de intervenções desnecessárias e contribui para melhores desfechos obstétricos. Dessa forma, pode-se avaliar, com o auxílio dessa ferramenta, que","options":{"A":"o parto precipitado é diagnosticado quando a dilatação cervical bem como a descida e expulsão fetal ocorrem num período de até 4 horas.","B":"a dilatação do colo, na fase ativa prolongada, ocorre numa velocidade menor que 1 cm/hora e é indicativo de cesárea quando ultrapassa a linha de alerta.","C":"o registro do uso da ocitocina não é necessário, porém se deve anotar a intensidade das contrações uterinas.","D":"a parada secundária de dilatação é diagnosticada por 2 toques sucessivos, com intervalo de 1 hora no trabalho de parto ativo."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860739","ankiGuid":"zGUAWaDr#q"},{"id":"anki-obstetricia-partograma-e-distocia-38e41daf978241f8","number":"0311l","sourceNumber":"0311l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"A distocia do parto é, por definição, a anormalidade no desenrolar do trabalho de parto, sendo apontada, nos Estados Unidos da América, como a indicação mais comum de cesárea em primigestas, e, no Brasil, não é muito diferente. Sobre a distocia, é INCORRETO afirmar:","options":{"A":"a distocia por hiperatividade sem obstrução é comum em primíparas e se caracteriza pela evolução rápida (menos que 3 horas) do trabalho de parto, sendo conhecida como parto taquitócico.","B":"a distocia tem como causa alterações em um ou mais dos três fatores determinantes para o sucesso do parto, a saber, a força, o trajeto e o objeto.","C":"a distocia tem como principal complicação a infecção, sobretudo, a corioamnionite e suas consequências para o feto e para a mãe, estando diretamente relacionada à duração do parto.","D":"a distocia funcional é definida como a presença de anormalidade do fator contrátil durante o trabalho de parto, o que influencia diretamente a progressão da dilatação cervical."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860740","ankiGuid":"xdMZ[Z[t?Z"},{"id":"anki-obstetricia-partograma-e-distocia-f6dcde8863485f3a","number":"0312l","sourceNumber":"0312l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Analise o partograma a seguir.\n\nCom base no partograma, o diagnóstico é de","options":{"A":"período expulsivo prolongado.","B":"parada secundária da descida.","C":"parada secundária de dilatação.","D":"fase ativa prolongada."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-b4fea0bb5f2894dd7e88bfc169a302ec5bbae13e.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860741","ankiGuid":"bnFvfJN85M"},{"id":"anki-obstetricia-partograma-e-distocia-3efb7613be95f2cf","number":"0313l","sourceNumber":"0313l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"M.K.T., 32 anos, G6 P5 C0 A0, com gestação de 40 semanas e 2 dias foi admitida em trabalho de parto conforme o partograma apresentado a seguir.\n\nApós 20 minutos da última avaliação (hora de registro 3), a paciente evoluiu para um parto vaginal sem lacerações e com recém-nascido em boas condições. A dequitação placentária ocorreu após 8 minutos do nascimento, sem intercorrências.\n\nCom relação à evolução desse trabalho de parto, assinale a opção correta.","options":{"A":"Trata-se de uma distócia funcional do trabalho de parto por hipoatividade.","B":"Trata-se de uma distócia funcional do trabalho de parto por hiperatividade.","C":"Trata-se de uma distócia de dilatação.","D":"Trata-se de um trabalho de parto com evolução normal.","E":"Trata-se de uma distócia de rotação"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-37683b74007052efd367a91efbcaa5d01c6adc68.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860742","ankiGuid":"iyEUu(@D=o"},{"id":"anki-obstetricia-partograma-e-distocia-c56902246e6779d6","number":"0314l","sourceNumber":"0314l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Uma gestante em trabalho de parto espontâneo se encontra com dilatação cervical de 6cm, feto em apresentação cefálica e dinâmica uterina de 6 contrações em um intervalo de 10 minutos. Qual dos termos a seguir adequadamente descreve essa situação?","options":{"A":"Contratilidade normal","B":"Hipersistolia","C":"Taquissistolia","D":"Hiperestímulo uterino"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860743","ankiGuid":"w&44)q([rt"},{"id":"anki-obstetricia-partograma-e-distocia-7e5eea2eccc55db2","number":"0315l","sourceNumber":"0315l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"O partograma esquematizado mostra a evolução de um parto por via vaginal, no qual ocorreu uma distócia da dilatação (fase ativa prolongada).\n\nUma das causas envolvidas para essa ocorrência é: Imagens anexas:","options":{"A":"Contrações uterinas ineficazes","B":"Desproporção cefalopélvica absoluta","C":"Desproporção cefalopélvica relativa","D":"Distócia de trajeto mole"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-b2b9d46e0cfa19753975f19e8363a1a908dc6829.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860744","ankiGuid":"AK0!Cc`>j&"},{"id":"anki-obstetricia-partograma-e-distocia-849fb38fbe18f945","number":"0316l","sourceNumber":"0316l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Considere que uma paciente de 28 anos de idade, G1 PV0 A0, com 40 semanas e seis dias de gestação, chega à maternidade relatando contrações uterinas dolorosas. Nega perda de líquido ou sangramento genital. Ao ser examinada, sua PA é de 120 x 80 mmHg e a FC é de 86 bpm. As contrações uterinas estão ocorrendo a cada cinco minutos e o BCF é 140 bpm. Ao toque vaginal, o colo está com 3 cm de dilatação e 50% apagado, a bolsa está íntegra e o polo cefálico está alto. Não desejou analgesia durante o acompanhamento do trabalho de parto.\n\nAnalise o padrão de dilatação do colo uterino e da descida do polo cefálico a seguir e assinale a alternativa correta.","options":{"A":"Trata-se de um caso de parada secundária da descida.","B":"Essa distócia é diagnosticada por dois toques sucessivos, com intervalo de duas horas ou mais, estando a paciente em trabalho de parto ativo.","C":"É frequente nesse tipo de distocia a contratilidade uterina deficiente.","D":"Estava indicado uso de fórceps na sexta hora de avaliação."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-f3b9b1a33e46c7e1c2c70ba31894d677f1a976b0.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860745","ankiGuid":"tfI{nzh-,6"},{"id":"anki-obstetricia-partograma-e-distocia-1d20b51d38e6ea6b","number":"0318l","sourceNumber":"0318l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"O partograma é um gráfico no qual são anotadas a progressão do trabalho de parto e as condições materno-fetais. Analise o seguinte partograma e assinale a alternativa correspondente com o padrão encontrado.","options":{"A":"Fase ativa prolongada.","B":"Parada secundária da descida.","C":"Desproporção cefálo-pélvica.","D":"Distócia funcional.","E":"Trabalho de parto fisiológico."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-e4004cee5793a0fbfb4018bc2f92b3f0639451f7.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860747","ankiGuid":"CO-:3g,wjJ"},{"id":"anki-obstetricia-partograma-e-distocia-1f9153c08a0ea5d9","number":"0319l","sourceNumber":"0319l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Mulher de 22 anos de idade, secundigesta com um parto cesáreo anterior com recém-nascido de 2632g há 4 anos. Chega ao pronto atendimento com dor em hipogástrio. Hoje está com 38 semanas e 2 dias de gestação e o pré-natal transcorreu sem intercorrências. Ao exame: PA 110x72 mmHg, FC 88 bpm, dinâmica uterina presente de 3 contrações em 10 minutos, BCF 144 bpm, altura uterina de 35 cm, toque com colo fino pérvio para 6 cm, apresentação cefálica, alta e fixa, bolsa integra, amnioscopia líquido claro com grumos grossos.\n\nApós análise do partograma, qual o diâmetro que estaria impedindo a descida da apresentação?","options":{"A":"A.","B":"B.","C":"C.","D":"D."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-7e02372829bf0e218cc42950e1d64094c45f4216.png","question_bank/media/obstetricia-partograma-e-distocia/paste-998604ab546b02bf58ac3a0e72fd7d000ebdc479.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860748","ankiGuid":"qq.?~#73`V"},{"id":"anki-obstetricia-partograma-e-distocia-b7bf8d9b7551904d","number":"0320l","sourceNumber":"0320l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Em acompanhamento de trabalho de parto a termo, uma parturiente encontra-se com três contrações uterinas a cada 10 minutos. A vitalidade fetal está boa e a dilatação cervical é de 5cm. Após algum tempo, constata-se colo completamente dilatado, bolsa rota, 5 contrações uterinas a cada 10 minutos, batimentos cardiofetais em 80bpm. A apresentação fetal encontra-se em –3, variedade de posição Occipto púbica. Considerando os dados do caso, indique a melhor conduta obstétrica.","options":{"A":"Parto cesariano de urgência.","B":"Fórceps ou vácuo-extrator.","C":"Manobra de Kristeler.","D":"Estimular o puxo e realizar episiotomia."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860749","ankiGuid":"tX{{7/@t<A"},{"id":"anki-obstetricia-partograma-e-distocia-434c439b414a1db9","number":"0321l","sourceNumber":"0321l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Em acompanhamento de trabalho de parto a termo, uma parturiente encontra-se com três contrações uterinas a cada 10 minutos. A vitalidade fetal está boa e a dilatação cervical é de 5cm. Após algum tempo, constata-se colo completamente dilatado, bolsa rota, 5 contrações uterinas a cada 10 minutos, batimentos cardiofetais em 80bpm. A apresentação fetal encontra-se em –3, variedade de posição Occipto púbica. Indique o momento no qual o partograma deve ser aberto.","options":{"A":"No início do período de dilatação.","B":"No início do período expulsivo.","C":"Na fase ativa do trabalho de parto.","D":"Na admissão da parturiente no centro obstétrico."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860750","ankiGuid":"F0,MQmyb4_"},{"id":"anki-obstetricia-partograma-e-distocia-ead77db3c48ba53e","number":"0322l","sourceNumber":"0322l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Em um partograma estão anotados os seguintes dados: Contrações: 4 de 40 segundos de forte intensidade; Bolsa íntegra; Dilatação: 4 cm pelas 3 últimas horas; Apresentação: ODP-1 FCF: 136. Pode-se concluir que","options":{"A":"a apresentação é cefálica, a posição é esquerda e o feto não está insinuado.","B":"a dinâmica uterina está adequada para a fase do trabalho de parto.","C":"se deve introduzir ocitocina em bomba de infusão para melhorar a dinâmica, pois o colo ainda está com 4 cm, sem modificações há 3 horas.","D":"se deve fazer analgesia para melhorar a provável distócia funcional.","E":"se deve indicar via alta pela parada de progressão."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860751","ankiGuid":"G,OJ@$kDlS"},{"id":"anki-obstetricia-partograma-e-distocia-fe68d5aeb94974e1","number":"0323l","sourceNumber":"0323l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"No preenchimento do partograma, além dos batimentos cardíacos fetais e das contrações uterinas, deve-se estar atento a:","options":{"A":"Dilatação do colo uterino, plano de De Lee da apresentação, variedade de posição, estado da membrana amniótica.","B":"Pressão arterial materna, dilatação do colo uterino, plano de De Lee da apresentação, estado da membrana amniótica.","C":"Dilatação do colo uterino, variedade de posição, plano de De Lee da apresentação, esvaecimento do colo uterino.","D":"Esvaecimento do colo uterino, estado da membrana amniótica, variedade de posição, pressão arterial materna."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860752","ankiGuid":"q2)doz]<Xa"},{"id":"anki-obstetricia-partograma-e-distocia-4437a285aa716cc5","number":"0324l","sourceNumber":"0324l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Parturiente com 6 cm de dilatação em 2 toques consecutivos, bolsa íntegra, liquido claro com grumos, dinâmica uterina de 3 contrações em 10 minutos com duração de 35 segundos cada, feto em plano -1 de De Lee. Avaliando o partograma, observa-se ter ultrapassado a linha de alerta. Nesse caso, as melhores opções de imediato são:","options":{"A":"analgesia peridural e misoprostol.","B":"amniotomia e ocitocina.","C":"amniotomia e misoprostol.","D":"misoprostol e deambulação."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860753","ankiGuid":"P8?$xv5Q#Z"},{"id":"anki-obstetricia-partograma-e-distocia-0bf9af0d5d2415a5","number":"0325l","sourceNumber":"0325l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Assinale a resposta INCORRETA:","options":{"A":"Na distocia de progressão, antes de indicar a cesariana, deve-se tentar solucionar sua principal causa, com a utilização de ocitocina e/ ou ruptura artificial das membranas, quando ocorrem contrações uterinas ineficazes.","B":"Na desproporção cefalopélvica, a cesariana é indicada corretamente, por meio do peso fetal.","C":"No mau posicionamento dos fetos, como nas variedades de posição posteriores e transversas persistentes, a rotação do polo cefálico deve ser tentada e, caso o trabalho de parto não evolua, deve-se realizar a cesariana.","D":"A apresentação de face não é indicação de cesariana, e o parto vaginal pode ser tentado.","E":"A apresentação pélvica não é indicação absoluta para indicação de cesárea"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860754","ankiGuid":"e#dhNu>I9Z"},{"id":"anki-obstetricia-partograma-e-distocia-7cff4fd4dfe06b36","number":"0326l","sourceNumber":"0326l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Primigesta, 22 anos, em fase ativa do trabalho de parto há 6 horas, bolsa rota há 2 horas, apresenta-se com dilatação completa, plano +3 de Delee, feto cefálico em occipto púbica. A frequência cardíaca fetal encontra-se em 80 bpm de forma sustentada, caracterizando sofrimento fetal. A conduta correta, neste momento, após orientar a paciente, é realizar","options":{"A":"cesariana de urgência, sem sondagem vesical de alívio, e anestesia peridural.","B":"episiotomia médio-lateral, sondagem vesical de alívio e aplicar fórcipe de Simpson.","C":"episiotomia médio-lateral, sondagem vesical de alívio e aplicar fórcipe de Piper.","D":"cesariana de urgência, com sondagem vesical de demora e anestesia raquidiana."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860755","ankiGuid":"As2_p)]QG%"},{"id":"anki-obstetricia-partograma-e-distocia-5146430e0a2ada5c","number":"0327l","sourceNumber":"0327l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"O partograma é uma ferramenta muito útil para acompanhar o desenvolvimento do trabalho de parto. Sobre o seu uso assinale a correta:","options":{"A":"O partograma auxilia a definir momentos para intervenção médica no decorrer do trabalho de parto.","B":"Uma das falhas do partograma é estar desatualizado quanto ao início do trabalho de parto, que atualmente é 5 cm.","C":"O uso do partograma inibe a realização de processos contra obstetras.","D":"O partograma utiliza como principal parâmetro o tamanho do conceito em relação a bacia materna."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860756","ankiGuid":"ADEtD/50Z-"},{"id":"anki-obstetricia-partograma-e-distocia-bade28c440e69a50","number":"0328l","sourceNumber":"0328l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Na assistência ao parto, a monitorização do bem-estar fetal é imperiosa. Com relação a esse cuidado, é correto afirmar:","options":{"A":"Com taquissistolia, a frequência cardíaca fetal (FCF) poderá ficar alterada, sendo que a retirada da ocitocina, se estiver sendo utilizada, a administração de uterolítico ou até mesmo a mudança de decúbito poderão reverter o quadro distócico e levar a FC ao padrão de normalidade.","B":"Se deve acompanhar o partograma de maneira que os controles da frequência cardíaca fetal (FCF) sejam feitos em cada avaliação, que deve ser de hora em hora ou a cada 2 horas.","C":"A presença de líquido meconial denota um processo de centralização fetal com desvio de sangue para os órgãos nobres (sofrimento feta compensado), acelerando o trânsito intestinal, relaxando os esfíncteres e eliminando mecônio; assim o parto deve ocorrer o mais breve possível.","D":"As desacelerações precoces são indicativas de hipoxemia fetal e, na sua presença, deve-se administrar oxigênio e acelerar o parto."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860757","ankiGuid":"bnWG)!GlE]"},{"id":"anki-obstetricia-partograma-e-distocia-b3f1923f77896453","number":"0329l","sourceNumber":"0329l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Primigesta, 23 anos de idade, 39 semanas de gestação, partograma conforme a figura. Exame físico: altura uterina 34 cm; cardiotocografia categoria I. Os diagnósticos segundo o partograma, e a conduta adequada, são:","options":{"A":"período pélvico prolongado e parada secundária da descida; realizar a cesárea.","B":"fase ativa prolongada e distócia de rotação; aplicar o fórcipe.","C":"parada secundária da dilatação e parada secundária da descida; aplicar o fórcipe.","D":"parada secundária da dilatação e período pélvico prolongado; realizar a cesárea.","E":"distócia funcional e período pélvico prolongado; aplicar o fórcipe."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860758","ankiGuid":"F5:ze)wD=C"},{"id":"anki-obstetricia-partograma-e-distocia-5fddf427332688ff","number":"0330l","sourceNumber":"0330l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Primigesta internada há 8 horas em trabalho de parto. A evolução do trabalho de parto está demonstrada no partograma abaixo. Foi diagnosticada a presença de desproporção cefalopélvica relativa.\n\nDe acordo com estes dados, responda, respectivamente, em qual período clínico do parto está ocorrendo esta distócia e a conduta:","options":{"A":"Período de dilatação e ocitocina endovenosa.","B":"Período de expulsão e ocitocina endovenosa.","C":"Período de expulsão e posição materna verticalizada.","D":"Período de dilatação e posição materna verticalizada."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-07bae6cb83887e85c59d0bebb3cb5faeef521b5f.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860759","ankiGuid":"yDKtu>,[/Z"},{"id":"anki-obstetricia-partograma-e-distocia-8544e4a0335c4333","number":"0331l","sourceNumber":"0331l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Considere a assistência ao parto de uma primigesta, de termo, com AU de 34 cm, dinâmica de 5 contrações em 10 minutos com 40 segundos de duração, colo totalmente dilatado, bolsa rota sem líquido, feto em apresentação cefálica em OET no plano zero de De Lee, com dificuldade de se identificarem as fontanelas pela presença de bossa e acavalgamento de sutura. Está nessas condições há 2 horas. A frequência cardíaca fetal está normal. Diante desses achados, é correto","options":{"A":"fazer fórcipe de Kjelland para abreviação do período expulsivo.","B":"fazer fórcipe de Kjelland por distócia de rotação.","C":"fazer cesárea por desproporção céfalo-pélvica.","D":"aguardar o final do período expulsivo, pois o feto está com boa vitalidade.","E":"introduzir ocitocina em bomba de infusão para coordenar as contrações e corrigir a distócia funcional."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860760","ankiGuid":"q<qb<fXBe5"},{"id":"anki-obstetricia-partograma-e-distocia-3e7896ed9b2e42bb","number":"0332l","sourceNumber":"0332l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Analise o partograma reproduzido a seguir e aponte o diagnóstico:","options":{"A":"Período pélvico prolongado","B":"Parada secundária da dilatação","C":"Parada secundária da descida","D":"Fase ativa prolongada"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-dc8e2c60e1fff6a0bd24348a5889b730a547d27a.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860761","ankiGuid":"izY2_e6;w1"},{"id":"anki-obstetricia-partograma-e-distocia-0f484f5c2eff43a5","number":"0333l","sourceNumber":"0333l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Uma primigesta, com quarenta semanas e quatro dias de gestação, encontra-se analgesiada, em período expulsivo há 3 h. Passou, então, a apresentar bradicardia fetal persistente, com BCF de 65 bpm há quatro minutos. Ao exame físico: altura uterina – 34 cm; e dinâmica uterina – quatro contrações de 35” em 10’. Ao toque vaginal, colo com dilatação total. Bolsa rota. Apresentação cefálica fletida, sem assinclitismo, em +2 de DeLee e variedade de posição OEA. Nessa situação hipotética, a conduta será fórceps de","options":{"A":"Simpson, com rotação de 45° no sentido horário.","B":"Simpson, com rotação de 45° no sentido anti-horário.","C":"Kielland, com rotação de 90° no sentido horário.","D":"Kielland, com rotação de 90° no sentido anti-horário.","E":"Kielland, sem rotação."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860762","ankiGuid":"sn1)C<;S:u"},{"id":"anki-obstetricia-partograma-e-distocia-d23391111280bf68","number":"0334l","sourceNumber":"0334l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Gestante é admitida na maternidade e a condução do seu parto, segue o seguinte partograma.\n\nConsiderando que o parto ocorreu em 2 horas e 40 minutos, assinale a alternativa gue NÃO ESTÁ ASSOCIADA a este tipo de parto.","options":{"A":"Hemorragia puerperal materna","B":"Infecção","C":"Laceração de trajeto de parto materna","D":"Lesão de plexo braquial no RN"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-1d6bab9c7786a5958078ca56a99d8922bba9b8e4.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860763","ankiGuid":"s`f>I$U_1y"},{"id":"anki-obstetricia-partograma-e-distocia-6797e4480d4131aa","number":"0335l","sourceNumber":"0335l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Paciente primigesta, gestação de 39 semanas, concepto adequado para a idade gestacional e pré-natal sem intercorrências. No seu plano de parto, a gestante solicita o uso de analgesia farmacológica para alívio da dor. Foi admitida às 6 horas no centro obstétrico em fase ativa do trabalho de parto, colo 90% apagado, com dilatação de 3cm e duas contrações de 30 segundos cada em 1 O minutos. Inicia-se a construção do partograma, apresentação cefálica, bolsa íntegra, 140bpm (batimento cardíaco fetal), plano de De Lee -3. Às 11 horas estava com colo fino, central, dilatado 6cm, apresentação fetal no plano zero de De Lee. Durante o toque houve ruptura espontânea das membranas com saída de líquido amniótico claro. Traçado cardiotocográfico com padrão fetal tranquilizador. Parturiente solicita analgesia. Às 13 horas, dilatação de 7cm, pólo fetal no plano + 1 de De Lee, quando recebeu analgesia. Às 15 horas apresentava 8cm de dilatação, pólo cefálico no plano + 1 de De Lee. Qual o diagnóstico desse caso?","options":{"A":"Parada secundária da descida","B":"Parada secundária da dilatação","C":"Fase ativa prolongada","D":"Fase ativa normal"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860764","ankiGuid":"qFefktTV#o"},{"id":"anki-obstetricia-partograma-e-distocia-b7a2fc876109228e","number":"0336l","sourceNumber":"0336l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Uma mulher de 32 anos, G1 P0, está com 42 semanas de gestação e está tendo o parto induzido por gravidez pós-termo. Ela teve um pré-natal sem complicações. A PA é de 100/60 mmHg. A altura do fundo uterino é de 40 cm. O colo está fechado, tem 3 cm de comprimento, e consistência firme. O obstetra decide utilizar um agente de maturação cervical, o misoprostol intravaginal. Aproximadamente 2 horas após colocar o misoprostol, a paciente tem um episódio de desaceleração fetal prolongado para 80 bpm por 6 minutos. Qual das seguintes é a etiologia mais provável da desaceleração prolongada?","options":{"A":"Descolamento de placenta","B":"Sepse","C":"Prolapso do cordão umbilical","D":"Incompetência istmo cervical","E":"Hiperestimulação uterina"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860765","ankiGuid":"z?[kz79mwB"},{"id":"anki-obstetricia-partograma-e-distocia-36fb1a684072948e","number":"0337l","sourceNumber":"0337l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Uma mulher de 26 anos, G2G1, com 41 semanas de gestação, está fazendo força há 3 horas sem progresso. Nesse tempo, pelo exame vaginal, permaneceu com o colo completamente dilatado, completamente apagado, no plano O, com a cabeça persistentemente na variedade no occipício posterior (OP). Qual das assertivas a seguir descreve acuradamente a situação?","options":{"A":"A variedade de occipício posterior frequentemente está associada a uma pelve ginecoide.","B":"O progresso do trabalho de parto é normal se a paciente não tiver um cateter epidural para analgesia, mas é anormal se estiver sendo utilizado analgesia epridural.","C":"Está contraindicada a cesariana.","D":"A parte óssea da cabeça fetal provavelmente está no plano de estrieto superior da pelve.","E":"A melhor descrição é que a paciente teve uma parada da descida."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860766","ankiGuid":"FHi|:[(*7z"},{"id":"anki-obstetricia-partograma-e-distocia-e9d5aac8fbee5bd6","number":"0338l","sourceNumber":"0338l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Sobre a distada fetal assinale a alternativa incorreta.","options":{"A":"Distada fetal é a ocorrência de anormalidades de tamanho ou posição fetal, resultando em dificuldades no parto.","B":"O diagnóstico da distada fetal é feito por exame clínico, ultrassonografia ou pela resposta à evolução do trabalho de parto.","C":"O tratamento da distada fetal é feito por manobras físicas para reposicionamento fetal, parto operatório vaginal ou cesariana.","D":"Na apresentação pélvica verdadeira o feto parece estar sentado com quadris e joelhos flexionados."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860767","ankiGuid":"AHL,[2;?H]"},{"id":"anki-obstetricia-partograma-e-distocia-9267a9427ae9d2ad","number":"0339l","sourceNumber":"0339l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Sobre as discinesias é correto afirmar:","options":{"A":"Hipoatividade uterina caracteriza-se pela diminuição da intensidade, frequência e atividade abaixo de 100 unidades Montevidéu (UM) acarretando em grave prejuízo materno e fetal.","B":"A hiperatividade costuma ser causada pelo parto obstruído ou pela ocitocina exagerada e o tratamento é decúbito dorsal com cabeceira a 30º ou emprego de inibidores.","C":"A hipertonia autêntica é causada pelo aumento anormal da frequência das contratações e o tratamento é o decúbito lateral e medicamentos inibidores.","D":"Na incoordenação de 2º grau notam-se no traçado pequenas contrações isoladas, alternadas com outras maiores que se espalham por zonas mais extensas. O parto tende a ser prolongado porque as isoladas são ineficazes e as que se estendem tem certa ação dilatadora.","E":"Na distocia cervical ativa o distúrbio é um espasmo funcional do orifício interno do colo, uma vez que não existe espasmo do orifício externo. Uma forma extrema da distocia cervical ativa é o anel de constrição que impede a distensão do istmo."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860768","ankiGuid":"FUH_7Jx6Vj"},{"id":"anki-obstetricia-partograma-e-distocia-8dc1e26cfe7b29ec","number":"0340l","sourceNumber":"0340l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Em relação à contratilidade uterina, assinale a alternativa CORRETA:","options":{"A":"Só está presente quando se inicia o trabalho de parto.","B":"São necessárias 4 contrações em um intervalo de 10 minutos para que se caracterize um trabalho de parto.","C":"O chamado triplo gradiente descendente é importante para que as contrações sejam efetivas para a dilatação do colo e para a descida da apresentação.","D":"O período de repouso fisiológico das contrações é o quarto período do parto, quando estas cessam.","E":"A contração uterina é responsável pelo trombotamponamento que ocorre no 4º período do parto."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860769","ankiGuid":"hlQ0i?L3Zy"},{"id":"anki-obstetricia-partograma-e-distocia-02ce547ef058ad02","number":"0341l","sourceNumber":"0341l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Observe o partograma abaixo e assinale a resposta INCORRETA.","options":{"A":"Ocorreu parada secundária da dilatação.","B":"Este quadro pode ser compatível com desproporção céfalo-pélvica.","C":"Não observamos sinais de sofrimento fetal.","D":"Há indicação de cesariana após horas de trabalho de parto.","E":"Este retrato da evolução do parto pode ser encontrado em casos de diabetes gestacional descompensado com fetos grandes para a idade gestacional."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-79e62d41f1a74f60b51de1564fe29a8de753c9d2.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860770","ankiGuid":"M=X:&/)[?]"},{"id":"anki-obstetricia-partograma-e-distocia-0f2497917319fe95","number":"0342l","sourceNumber":"0342l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Primigesta, 29 anos, 41 semanas de gestação, apresenta evolução do trabalho de parto segundo partograma abaixo. Altura uterina 39 cm, avaliação da bacia: conjugado diagonal: 11,0 cm; espinhas ciáticas salientes, bituberoso: 10 cm e ângulo subpúbico < 90°. À meia-noite, foi instalada analgesia peridural contínua.\n\nConsiderando a avaliação realizada às 3:00 h, o diagnóstico do partograma e a conduta, RESPECTIVAMENTE, são:","options":{"A":"parada secundária da descida / aplicação do fórcipe de Kielland.","B":"parada secundária da rotação / realização da cesárea.","C":"período pélvico prolongado / ultimação do parto com o vácuo-extrator.","D":"parada secundária da descida / realização da cesárea.","E":"parada secundária da rotação / aplicação do fórcipe de Kielland."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-b9c42e44738099880219f13956f1c4176461e40a.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860771","ankiGuid":"k92eC(f;5Y"},{"id":"anki-obstetricia-partograma-e-distocia-1b5bdc22d3a52782","number":"0343l","sourceNumber":"0343l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Observe o partograma seguinte.\n\nO diagnóstico desse partograma é","options":{"A":"parada secundária da descida.","B":"parto eutócico fisiológico.","C":"parto taquitócito.","D":"divisão pélvica prolongada.","E":"fase ativa prolongada."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-6f79eaea6f1a7bae859693a6e5fc10ddf908e181.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860772","ankiGuid":"sY+(XnRFKC"},{"id":"anki-obstetricia-partograma-e-distocia-3b32b026ea4379bc","number":"0344l","sourceNumber":"0344l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"No período expulsivo prolongado, com feto em apresentação cefálica fletida, associado à hipocinesia uterina, a medida mais apropriada para observar o desprendimento fetal é:","options":{"A":"Manobra de kristeller","B":"Aplicação de fórceps de alívio","C":"Infusão venosa de Ocitocina","D":"Operação cesariana"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860773","ankiGuid":"f(>->RGRxh"},{"id":"anki-obstetricia-partograma-e-distocia-0390ded5d70a21a5","number":"0345l","sourceNumber":"0345l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"No que se refere aos partogramas apresentados, é correto afirmar que o partograma de número","options":{"A":"1 representa uma distocia de descida chamada fase ativa prolongada. A causa dessa distocia é a desproporção cefalopélvica que, na maioria dos casos, é secundária a apresentações fetais defletidas ou em variedades de posição transversas ou posteriores.","B":"2 representa uma distocia de dilatação chamada parada secundária da dilatação. A principal causa dessa anormalidade é a presença de contrações em número ou qualidade insuficiente para promover a dilatação do colo uterino.","C":"3 representa uma distocia de descida chamada parada secundária da descida. A verticalização da parturiente, a rotura de bolsa amniótica e a rotação manual do polo cefálico podem auxiliar em sua correção.","D":"4 representa uma distocia de descida chamada período expulsivo prolongado. A principal causa dessa anormalidade é a desproporção cefalopélvica.","E":"4 representa uma distocia de dilatação chamada parto taquitócico. Essa distocia está associada a maiores riscos de hemorragia puerperal, tanto por atonia uterina quanto por lacerações de trajeto."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-0b78d88c7ef67f45a6c2fbe646a6cbdeab4fe3f5.png","question_bank/media/obstetricia-partograma-e-distocia/paste-cb5dd289076e32a0fcf9ebb0ed64fa4aba79d5f7.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860774","ankiGuid":"P:%.@$JZhc"},{"id":"anki-obstetricia-partograma-e-distocia-c72852ea5fd2e98a","number":"0346l","sourceNumber":"0346l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"A partir de quantas contrações em 10 minutos durante o trabalho de parto, é considerado taquissistolia?","options":{"A":"4","B":"5","C":"6","D":"7","E":"8"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860775","ankiGuid":"F~YkTktvUU"},{"id":"anki-obstetricia-partograma-e-distocia-986ba0cf270eb88f","number":"0348l","sourceNumber":"0348l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Frente a um diagnóstico de distócia por hiperatividade (parto taquitócico) sem obstrução à passagem do feto, a melhor orientação será realizar a","options":{"A":"cesárea, evitando-se assim a ocorrência de rotura uterina.","B":"amniotomia precoce, sem analgesia, auxílio manual à ampliação do canal de parto (colo e períneo).","C":"amniotomia precoce com agulha de raquianestesia, uterolítico e observação rigorosa da dinâmica uterina.","D":"ocitocina em bomba de infusão, bloqueio pudendo, rápida hidratação venosa e ampla episiotomia.","E":"amniotomia tardia, analgesia precoce, revisão cuidadosa do canal de parto e observação rigorosa do recém- nascido."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860777","ankiGuid":"AI[>y:p=wD"},{"id":"anki-obstetricia-partograma-e-distocia-0e28ebcc250d9ab1","number":"0349l","sourceNumber":"0349l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Primigesta de 21 anos de idade, está com 38 semanas de gestação e iniciou trabalho de parto espontâneo. O partograma e a cardiotocografia estão apresentados a seguir.\n\nQual é o método indicado para ultimação do parto?","options":{"A":"Abreviação com vácuo extrator.","B":"Cesárea segmentar transversa.","C":"Aguardar parto espontâneo.","D":"Rotação com fórcipe Kielland."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-b822eeeb98f8275fb0b8b60b6e4f83e784c2fa03.png","question_bank/media/obstetricia-partograma-e-distocia/paste-45096a4c5f0eb922d9f5d19e52b76087fe58a7f6.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860778","ankiGuid":"esr+H_~LcG"},{"id":"anki-obstetricia-partograma-e-distocia-ea98ba7bb5de65df","number":"0350l","sourceNumber":"0350l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Paciente hígida foi submetida a maturação de colo com misoprostol e posterior indução de parto por pós-datismo, conforme partograma apresentado.\n\nPaciente evoluiu com dor e dificuldade de deambulação no pós-parto, necessitando analgésico de resgate. No 2º dia pós- parto, apresenta temperatura oral aferida de 38,6 C. No exame clínico, está em bom estado geral e eupneica. O abdome é doloroso à palpação, com sinal de descompressão brusca negativo e ruídos hidroaéreos presentes. A ferida cirúrgica tem bom aspecto. A loquiação é fétida. A conduta inicial indicada para essa paciente é:","options":{"A":"Administrar antibiótico.","B":"Aspirar restos ovulares.","C":"Anticoagulação plena.","D":"Histerectomia subtotal."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-56a3014300e500b23f2901a347354b4f0783f8e6.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860779","ankiGuid":"MTzN&:HI#B"},{"id":"anki-obstetricia-partograma-e-distocia-60134e1af46abe8a","number":"0352l","sourceNumber":"0352l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Observe o partograma a seguir\n\nConsiderando o partograma, o obstetra resolveu realizar uma cardiotocografia às 07 horas, a fim de monitorar o período expulsivo, cujo resultado está apresentado abaixo.\n\nCom base na cardiotocografia e no partograma, marque a afirmativa correta.","options":{"A":"Deve-se realizar manobras de ressuscitação intrauterina e abreviação do período expulsivo com a aplicação de fórceps.","B":"A presença de mecônio às 06 horas no partograma já confirmava o diagnóstico de sofrimento fetal intraparto.","C":"O índice PH de 7,25 no sangue colhido do cordão umbilical no pós-parto imediato confirma o diagnóstico de sofrimento fetal agudo (intraparto).","D":"Observam-se na cardiotocografia desacelerações do tipo I (DIP umbilical) e manobras de ressuscitação intrauterina e cesariana estão indicadas."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-53d51a02448358aafa8a4e712748e1053e7c9fd0.png","question_bank/media/obstetricia-partograma-e-distocia/paste-2ce1bf2e732783e68d18d31e5c53129d5b1d16d8.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860781","ankiGuid":"gn0R[&+Co]"},{"id":"anki-obstetricia-partograma-e-distocia-87c58d80e6cdbe63","number":"0353l","sourceNumber":"0353l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Observe o partograma a seguir.\n\nCom base no partograma apresentado, marque a afirmativa correta.","options":{"A":"Observa-se uma desproporção céfalo-pélvica, e a cesariana é indicada.","B":"A variedade de posição no momento da abertura do partograma é occipito-esquerda posterior.","C":"Por se tratar de um período pélvico prolongado, manobras como a verticalização da posição materna podem auxiliar na ultimação do parto.","D":"Após 04 horas, observa-se uma parada secundária de descida, e a otimização das contrações com o uso de ocitocina ajudará na ultimação do parto."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-53d51a02448358aafa8a4e712748e1053e7c9fd0.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860782","ankiGuid":"svqpz{?;r^"},{"id":"anki-obstetricia-partograma-e-distocia-b94df4c315b97c14","number":"0354l","sourceNumber":"0354l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Considere o traçado de partograma mostrado na imagem abaixo.\n\nNesse caso,","options":{"A":"a linha de batimento cardíaco fetal mostra que o feto não está bem oxigenado.","B":"a linha de alerta é a segunda linha oblíqua, que se encontra mais à direita.","C":"observa-se desproporção céfalo-pélvica com possível formação de bossa no recém-nascido.","D":"os triângulos representam a dilatação cervical, que ocorreu de forma progressiva e fisiológica.","E":"o partograma mostra contrações uterinas fracas e irregulares."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-2d36fa2b8674bbd39bc71a5b9117598e04f56f66.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860783","ankiGuid":"ky]>M&pth%"},{"id":"anki-obstetricia-partograma-e-distocia-2ec3476cd1c9b069","number":"0355l","sourceNumber":"0355l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Primigesta de 39 semanas fez apenas uma consulta pré-natal de primeiro trimestre, que evidenciava glicemia de jejum 95 mg/dl. Foi admitida em trabalho de parto espontâneo e a evolução está descrita no partograma em anexo.\n\nDiante da interpretação adequada do partograma, assinale o diagnóstico e conduta para o caso:","options":{"A":"Período expulsivo prolongado. Indicar fórcipe de alívio.","B":"Distocia funcional por hipoatividade. Prescrever ocitocina endovenosa.","C":"Desproporção. Cefalopélvíca. Indicar cesárea.","D":"Parada secundária da dilatação. Indicar fórcipe de Simpson."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-907c47829b4d195827f19fd729756be9a348c1d9.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860784","ankiGuid":"Rd9odfJ3V$"},{"id":"anki-obstetricia-partograma-e-distocia-192f8741b692b467","number":"0356l","sourceNumber":"0356l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Parturiente, 38 anos de idade, 40 semanas, primi- gesta, apresenta evolução do trabalho de parto conforme partograma da figura.\n\nExame físico: sinais vitais preservados, altura uterina 35cm, feto único. Avaliação da bacia: conjugado diagonal medindo 13 cm, espinhas ciáticas médias, ângulo subpúbico de 90° e medida do diâmetro bituberoso de 11 cm. A distocia diagnosticada pelo partograma e a provável causa, respectivamente, são:","options":{"A":"Fase ativa prolongada, desproporção cefalopélvica absoluta.","B":"Parada secundária da dilatação, desproporção cefalopélvica relativa.","C":"Parada secundária da descida, defletida de primeiro grau.","D":"Parada prolongada da dilatação, vício pélvico relativo.","E":"Fase ativa prolongada, defletida de primeiro grau."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-77858a5576efdd62ed2cfde2819edaf16e360d76.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860785","ankiGuid":"h}@2]s;$?>"},{"id":"anki-obstetricia-partograma-e-distocia-0a8c07f1128cfe90","number":"0357l","sourceNumber":"0357l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Mulher. 25a, G2P1C0A0, com idade gestacional de 39 semanas procura o pronto atendimento com queixa de contrações. Exame obstétrico à admissão: altura uterina de 39cm, batimentos cardíacos fetais= 144bpm e dinâmica uterina: 3 contrações de moderada intensidade e duração média de 45 segundos em 10 minutos. A evolução do trabalho de parto está representada no partograma:\n\nO DIAGNÓSTICO É:","options":{"A":"Desproporção cefalopélvica.","B":"Distócia de rotação.","C":"Parto eutócico.","D":"Período expulsivo prolongado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-4efde66626e5eb580e522afdf6899160d88ad019.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860786","ankiGuid":"bw5hB+.m!X"},{"id":"anki-obstetricia-partograma-e-distocia-35fa49ef525c0987","number":"0358l","sourceNumber":"0358l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Ao analisar o partograma de uma nulípara, 38 semanas de gestação, você observa que a mesma internou com 7 centímetros de dilatação cervical, apresentação cefálica, bolsa das águas rota e boa vitalidade fetal. Após 4 horas do exame acima descrito, observa-se que a dilatação cervical permanece a mesma, apesar da existência de contrações uterinas em número e intensidade adequados. A causa dessa distócia, na maioria das vezes, é devido a:","options":{"A":"Sinclitismo de Nagëlle","B":"Circular cervical de cordão","C":"Apresentações fetais defletidas","D":"Amniorrexe prematura"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860787","ankiGuid":"Iw:575BxEY"},{"id":"anki-obstetricia-partograma-e-distocia-50ba469fc211d8b3","number":"0359l","sourceNumber":"0359l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Ao analisar o partograma de uma parturiente em franco trabalho de parto, foram observadas parada secundária da dilatação com 8 cm e apresentação cefálica em –1 de DeLee, acompanhadas de dinâmica uterina intensa de cinco contrações em dez minutos. Com base nesse caso hipotético, assinale a alternativa que apresenta, respectivamente, o diagnóstico mais provável e a melhor conduta a ser adotada.","options":{"A":"desproporção cefalopélvica e fórcipe","B":"desproporção cefalopélvica e cesariana","C":"distocia funcional e amniotomia","D":"distocia funcional e cesariana","E":"distocia de rotação e fórcipe"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860788","ankiGuid":"y0JFt0J7bI"},{"id":"anki-obstetricia-partograma-e-distocia-eee6397a621caa81","number":"0360l","sourceNumber":"0360l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Parturiente de 32 anos, G3P2A0C0, está sob assistência ao trabalho de parto e com evolução apresentada no partograma a seguir.\n\nO diagnóstico identificado na evolução do trabalho de parto e a conduta são:","options":{"A":"parada secundária da dilatação e descida; cesárea.","B":"parada secundária da dilatação e descida; fórcipe de Kjelland.","C":"parada secundária da dilatação; fórcipe de Kjelland.","D":"parada secundária da dilatação; cesárea."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-06e2e65c32bc92c6ff6206ab1ea6dcd2dfc1dcfb.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860789","ankiGuid":"fMkNHU;sq+"},{"id":"anki-obstetricia-partograma-e-distocia-3eb9481a8fefd757","number":"0361l","sourceNumber":"0361l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Primigesta, 30 anos, com 40 semanas, é internada na fase ativa do trabalho de parto, com boa vitalidade fetal na admissão. Pré-natal sem intercorrências. Ela traz um plano de parto no qual rejeita o uso de ocitócicos, analgesia farmacológica e episiotomia. A parturiente se mantém bastante ativa, com alternância de posturas. As 21 horas, ela é reavaliada, apresentando sinais vitais normais, altura uterina de 37 cm, atividade uterina de 4 contrações de 50 segundos/10 minutos e batimentos cardíacos fetais sem desacelerações. O registro gráfico do trabalho de parto está representado na figura.\n\nEscolha a alternativa com a melhor conduta nesse caso.","options":{"A":"Indicar resolução de gestação por parto cesárea.","B":"Promover corioamniorrexe artificial imediatamente.","C":"Convencer a paciente a aceitar analgesia farmacológica.","D":"Explicar sobre a necessidade de ocitocina endovenosa."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-edfd78d93974d20b20b80b8c25cd02666f2fbf9a.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860790","ankiGuid":"k,Ai?t6mHl"},{"id":"anki-obstetricia-partograma-e-distocia-891627e427a9f2d1","number":"0362l","sourceNumber":"0362l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"O partograma abaixo caracteriza:","options":{"A":"Fase de latência.","B":"Vício pélvico.","C":"Distocia funcional.","D":"Expulsivo prolongado."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-c58ddfb5880e8c189a6ad09d84c4e0f814371c65.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860791","ankiGuid":"h4zbkotQ#E"},{"id":"anki-obstetricia-partograma-e-distocia-c0a3a5bdfd560b40","number":"0363l","sourceNumber":"0363l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Qual a melhor classificação desse partograma?","options":{"A":"Descida lenta da apresentação","B":"Parada secundária da dilatação","C":"Parada secundária da descida","D":"Parto taquitócico"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-380a1409938d175507fbe8774413431892edbafa.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860792","ankiGuid":"jU~{./@IL^"},{"id":"anki-obstetricia-partograma-e-distocia-620c69cd48dd92f0","number":"0366l","sourceNumber":"0366l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"G5 P4 (3PN 1C), apresenta hipertonia uterina no final da fase de dilatação. Após a retirada da ocitocina e com início do expulsivo, cessa a hipertonia, mas ocorre sangramento volumoso. A paciente queixa de dor na escápula direita e evolui com hipotensão, hematúria na sonda, desaceleração dos batimentos cardíacos fetais e subida da apresentação. A hipótese diagnóstica é:","options":{"A":"Descolamento de placenta.","B":"Toco traumatismo materno.","C":"Rutura uterina.","D":"Distócia cervical dinâmica.","E":"Inversão do tríplice gradiente descendente."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860795","ankiGuid":"yKX}kS*#-q"},{"id":"anki-obstetricia-partograma-e-distocia-fb35916fb38c37f0","number":"0367l","sourceNumber":"0367l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Em relação ao partograma, é correto afirmar:","options":{"A":"A fase latente do trabalho de parto tem duração menor que a fase ativa, geralmente até 12 horas, e a conduta deve ser expectante.","B":"Se a linha de alerta for ultrapassada, existe o risco iminente de sofrimento fetal.","C":"A parada secundária de descida é uma distocia do período de dilatação, e a fase ativa prolongada é uma distocia do período pélvico.","D":"Na parada secundária de dilatação, a dilatação permanece a mesma em dois ou mais toques consecutivos, realizados em intervalo de duas ou mais horas entre eles, e a causa principal é a desproporção cefalopélvica relativa ou absoluta."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860796","ankiGuid":"vmeqi]];4U"},{"id":"anki-obstetricia-partograma-e-distocia-fa64b8acc798fbd1","number":"0368l","sourceNumber":"0368l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Gestante, 22 anos, G2P0A1, idade gestacional 39 semanas é admitida para assistência ao trabalho de parto. Na hora de registro 8 do partograma a equipe assistencial reavalia a gestante e faz o seguinte registro conforme figura abaixo.\n\nAssinale a alternativa que apresenta a conduta MAIS ADEQUADA e sua justificativa CORRETA.","options":{"A":"Acompanhamento habitual, pois o diagnóstico é de trabalho de parto eutócico","B":"Deambulação materna, pois o diagnóstico é de parada secundária de descida","C":"Operação cesariana, pois o diagnóstico é de desproporção cefalopélvica","D":"Prescrição de ocitocina, pois o diagnóstico é de parada secundária de dilatação"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-e4314d264537227a895a3f9fa903be7370258402.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860797","ankiGuid":"uUZz#@-MK"},{"id":"anki-obstetricia-partograma-e-distocia-ebaf2efb40084975","number":"0371l","sourceNumber":"0371l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Mulher, 25a, G1P0A0C0, com idade gestacional de 39 semanas e 3 dias apresenta evolução do trabalho de parto segundo o partograma abaixo:\n\nO DIAGNÓSTICO É:","options":{"A":"Parada secundária da descida por desproporção céfalo-pélvica.","B":"Parada secundaria da dilatação por distocia funcional.","C":"Fase ativa prolongada por contratilidade uterina insuficiente.","D":"Parto taquitócico por distocia funcional."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-58e17cf11f58e63df2165e9a1499ff477248a70e.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860800","ankiGuid":"Bch*f:6*S,"},{"id":"anki-obstetricia-partograma-e-distocia-2ed851e0ae38c63a","number":"0372l","sourceNumber":"0372l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Primigesta de termo, apresenta o seguinte partograma:\n\nÉ correto afirmar que há:","options":{"A":"Evolução adequada da descida devendo-se aguardar mais de 1 ou 2 horas para o parto.","B":"Desproporção cefálico-pélvica, com grande chance de necessidade de cesárea.","C":"Distocia de rotação devendo-se aplicar fórceps de rotação (Kielland).","D":"Parada secundária da descida devendo-se aplicar fórceps de alívio."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-aec7c4e527991a98d47878b45e4eb93bcec0e87c.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860801","ankiGuid":"A36DP]PyLi"},{"id":"anki-obstetricia-partograma-e-distocia-beed1907b6c1c35a","number":"0373l","sourceNumber":"0373l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Em relação ao partograma abaixo, é correto afirmar:","options":{"A":"Caracteriza-se por um parto eutócico;","B":"Não permite identificar risco apra o feto;","C":"É típico de amniorrexe prematura;","D":"Identificar-se uma parada de progressão","E":"Nenhuma das anteriores"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-d63d0ed8e194c51b4f73c7d02b429b354b781a07.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860802","ankiGuid":"Mw,VefI_Yv"},{"id":"anki-obstetricia-partograma-e-distocia-ff16b9b0bfb5769b","number":"0374l","sourceNumber":"0374l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"O prolongamento da fase ativa do trabalho de parto deve-se a um dos fatores a seguir, exceto:","options":{"A":"Desproporção cefalopélvica.","B":"Maior tônus da musculatura uterina.","C":"Uso de anestesia de condução.","D":"Má posição fetal."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860803","ankiGuid":"q?Od3>:w%p"},{"id":"anki-obstetricia-partograma-e-distocia-d7605ec27083c2d2","number":"0375l","sourceNumber":"0375l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Primigesta, 21 anos, sem doenças, pré-natal sem intercorrências, interna para assistência obstétrica após início espontâneo do trabalho de parto com 40 semanas. Em uso apenas de polivitamínicos. Exame: sinais vitais e exame físico geral normais. Altura uterina 36 cm. A evolução de seu trabalho de parto está demonstrada no partograma abaixo (Figura1).\n\nno momento, a paciente está em posição verticalizada, deambula com frequência e tem aceito métodos de alívio não farmacológicos da dor. Às 15 horas, na ausculta fetal intermitente, surgiram dúvidas sobre a presença de desacelerações, motivo pelo qual foi realizado o traçado contínuo da frequência cardíaca fetal mostrado como Figura 2.\n\nApós análise de ambas as figuras, escolha a melhor conduta na condução deste trabalho de parto.","options":{"A":"Conduta expectante.","B":"Resolução da gestação por cesárea.","C":"Prescrição de ocitocina endovenosa.","D":"Instituição de manobras de reanimação fetal."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-403a13e558cd838776d651b759483965a988ca79.png","question_bank/media/obstetricia-partograma-e-distocia/paste-468c410fa36d71f5d0fd3eaa1796fac4a55174b7.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860804","ankiGuid":"tFWjZW8Q2S"},{"id":"anki-obstetricia-partograma-e-distocia-857a6b14dc7be995","number":"0376l","sourceNumber":"0376l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Mulher de 23 anos, primigesta, com gestação tópica de 39s e 3 dias, encontra-se em trabalho de parto. Considerando o partograma abaixo sua evolução indica:","options":{"A":"Fase ativa prolongada.","B":"Parada secundária da dilatação.","C":"Desproporção cefálo-pélvica.","D":"Trabalho de parto fisiológico."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-1e4692c619c8cc431ac645b70e1a1a3d9f0b314f.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860805","ankiGuid":"hs]5bbJE;o"},{"id":"anki-obstetricia-partograma-e-distocia-a71e8c1292ab51d7","number":"0377l","sourceNumber":"0377l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Mulher, 25a, primigesta, idade gestacional de 39 semanas, apresentou evolução do trabalho de parto e parto de acordo com o partograma:\n\nAS COMPLICAÇÕES ASSOCIADAS A ESSA EVOLUÇÃO SÃO:","options":{"A":"Lesão de trajeto, hipotonia uterina e hemorragia ventricular no recém-nascido.","B":"Rotura uterina, sofrimento fetal agudo e distócia de ombro.","C":"Tocotraumatismo, sofrimento fetal agudo e distócia funcional.","D":"Atonia uterina, hemorragia ventricular no recém-nascido e distócia de ombro."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-f14662f8f5c8ea15449c2ac5d9fb663de98605ab.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860806","ankiGuid":"uYL$e@9osC"},{"id":"anki-obstetricia-partograma-e-distocia-5b21adc67cdbd7a5","number":"0378l","sourceNumber":"0378l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Analisando o partograma abaixo, qual o diagnóstico e conduta?","options":{"A":"Partorama normal. Seguir com assitência ao parto","B":"Desproporção céfalo-pélvica. Fazer ocitocina","C":"Parada de dilatação. Realizar cesariana","D":"Distócia de rotação. Fazer uso de fórceps"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-49b01b8f34aaa2b5bd10feb3987264226528c6de.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860807","ankiGuid":"OiD9DF=^=-"},{"id":"anki-obstetricia-partograma-e-distocia-a89a1c54c6a11dcc","number":"0379l","sourceNumber":"0379l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Considere o registro partograma abaixo.\n\nA impressão diagnóstica e conduta mais adequada são:","options":{"A":"Período pélvico prolongado, estimular deambulação.","B":"Parto taquitócico, realizar revisão do canal de parto.","C":"Parada secundária da dilatação, administrar ocitócitos.","D":"Parada secundária da descida, indicar parto cesariano.","E":"Parto eutócico, orientar sobre os eventos fisiológicos do trabalho de parto."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-b4e0763eed934d175a02a417ad0ae331dd98e07f.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860808","ankiGuid":"E|:%}fa~bD"},{"id":"anki-obstetricia-partograma-e-distocia-109e385e14e1746a","number":"0380l","sourceNumber":"0380l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Você assume o plantão no centro obstétrico e se depara com o partograma abaixo.\n\nQual a principal causa desse tipo de distócia?","options":{"A":"Assinclitismo.","B":"Taquissistolia.","C":"Hipocontratilidade uterina.","D":"Desproporção cefalopélvica."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-54f18fc718163cb983b147e6ec4952c804e23a2f.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860809","ankiGuid":"tcuguGVYk)"},{"id":"anki-obstetricia-partograma-e-distocia-facaee27d05a360b","number":"0381l","sourceNumber":"0381l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Primigesta, 41 semanas, foi submetida a preparo de colo e indução do parto. Analise o partograma apresentado na figura.\n\nNesse caso, as características importantes do partograma, para o prognóstico de sucesso do parto por via vaginal, são:","options":{"A":"Variedade de posição OEP e batimentos cardíacos fetais normais.","B":"Dilatação do colo uterino de 7 cm e 4 contrações uterinas em 10 minutos.","C":"Descida da apresentação em +1 e bolsa das águas rota.","D":"Bolsa das águas íntegra e ter completado a rotação interna para OP.","E":"Dilatação do colo uterino de 7 cm e bolsa das águas íntegra."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-5dcb931a008b6901a58f783f76a8a913ec21ca0f.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860810","ankiGuid":"J;/pIKKB#3"},{"id":"anki-obstetricia-partograma-e-distocia-9c55a7bb2a5ad006","number":"0384l","sourceNumber":"0384l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Em relação ao partograma, é CORRETO afirmar:","options":{"A":"A parada secundária de dilatação é diagnosticada por 2 toques sucessivos e com intervalo de 1 hora no trabalho de parto ativo.","B":"O parto precipitado é diagnosticado quando a dilatação cervical e a descida e expulsão fetal ocorrem num período de até 4 horas.","C":"Não há necessidade de se registrar o uso da analgesia, porém deve-se anotar aintensidade das contrações uterinas, a infusão de drogas, os batimentos cardíacos fetais, a dilatação cervical e a posição e descida do polo cefálico.","D":"Por convenção, registra-se a dilatação cervical com um quadrado e a variedade deposição fetal com uma circunferência.","E":"Na fase ativa prolongada, a dilatação do colo ocorre numa velocidade < 1 cm/hora e éindicativo de cesárea quando ultrapassa a linha de alerta."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860813","ankiGuid":"t+A:hIGcz@"},{"id":"anki-obstetricia-partograma-e-distocia-e6021fe48cb5001c","number":"0385l","sourceNumber":"0385l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Primigesta com 38 semanas de gestação chegou ao centro obstétrico em trabalho de parto. A altura uterina era de 36 cm, e o peso fetal estimado de 3.600 g. A evolução do trabalho de parto pode ser visualizada no partograma abaixo.\n\nQual a próxima conduta obstétrica indicada às 6 horas?","options":{"A":"Infundir ocitocina.","B":"Aplicar fórceps de Kielland.","C":"Indicar apalgesia peridural.","D":"Indicar cesariana.","E":"Iniciar os esforços expulsivos."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-4c3a384d131466279b333196b9c790f677315379.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860814","ankiGuid":"O{+bOD+#HK"},{"id":"anki-obstetricia-partograma-e-distocia-ceca604ebc71bc96","number":"0386l","sourceNumber":"0386l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Observe o partograma abaixo, referente à primigesta, 38 semanas, BCF 160 bpm, dinâmica uterina 4/10min, fortes.\n\nQual deve ser sua conduta?","options":{"A":"Aguardar o parto normal que deve ocorrer em pouco tempo.","B":"Aumentar a infusão de ocitocina pois a descida da cabeça não está ocorrendo na velocidade desejada.","C":"Indicar cesária, já que a progressão do parto não está adequada.","D":"Indicar um fórceps de alívio, já que há início de sofrimento fetal e o parto ainda vai demorar."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-ba05d1e0c903a56891aa9fcddb6c51be136316d6.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860815","ankiGuid":"AXc3sUCv-8"},{"id":"anki-obstetricia-partograma-e-distocia-8cf7b72acbdd26e2","number":"0387l","sourceNumber":"0387l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"O partograma abaixo sugere:","options":{"A":"Fase ativa prolongada.","B":"Parada secundária da dilatação.","C":"Desproporção cefalopélvica.","D":"Distocia funcional.","E":"Trabalho de parto fisiológico"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-00b00f2482feed436e9c7106f1f78daab2ac4c58.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860816","ankiGuid":"bie:8fDX%g"},{"id":"anki-obstetricia-partograma-e-distocia-14d84dfaed4c8cd9","number":"0388l","sourceNumber":"0388l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"No acompanhamento de um trabalho de parto, o partograma descreve na última hora, dilatação total e feto em altura de apresentação +3 de De Lee, em apresentação cefálica em OP. A conduta mais adequada em relação ao parto é:","options":{"A":"Aguardar parto espontâneo e se necessário aplicar fórcipe de alívio.","B":"Condução do caso com ocitocina por se tratar de distócia de rotação.","C":"Cesárea por distócia de apresentação.","D":"Fórcipe de kielland por se tratar de distócia de rotação."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860817","ankiGuid":"vO?^#vDh.p"},{"id":"anki-obstetricia-partograma-e-distocia-62a30d5671691d33","number":"0390l","sourceNumber":"0390l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Primigesta de 40 semanas de idade gestacional é admitida em trabalho de parto com toque vaginal de 4 cm, 100% esvaecido, apresentação cefálica em plano -2 de DeLee. A frequência cardíaca fetal está em 150 bpm; rítmica e a dinâmica uterina se apresenta com 4 contrações fortes de 45 segundos em 10 minutos. Duas horas após evolui para parto vaginal sem analgesia. As complicações associadas a essa evolução são:","options":{"A":"Inversão uterina, hipotonia uterina e hemorragia cerebral no recém-nascido.","B":"Hipotonia/atonia uterina, laceração de trajeto e hemorragia cerebral no recém-nascido.","C":"Acretismo placentário, hemorragia do quarto período, hemorragia retiniana no recémnascido.","D":"Laceração de trajeto, sofrimento fetal agudo e retenção placentária."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860819","ankiGuid":"sD[N#ETpLd"},{"id":"anki-obstetricia-partograma-e-distocia-442a5c016d4ed74c","number":"0391l","sourceNumber":"0391l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Primigesta de 40 semanas de idade gestacional, admitida em trabalho de parto, submetida a analgesia com 6 cm de dilatação, quando já apresentava bolsa rota. A partir desse momento foi conduzida com ocitocina mantendo 4 contrações fortes, em média, em 10 minutos. A evolução do parto está representada no partograma abaixo.\n\nA conduta é:","options":{"A":"Fórcipe de Kielland por distocia de rotação.","B":"Cesárea por distocia funcional.","C":"Fórcipe de Simpson para abreviação do período expulsivo.","D":"Cesárea por desproporção cefalopélvica."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-3013ece99b57c4d0df1b1ed3d019146e35932988.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860820","ankiGuid":"hs3x$?dZWB"},{"id":"anki-obstetricia-partograma-e-distocia-3cdb55dff9abec7f","number":"0392l","sourceNumber":"0392l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Paciente de 20 anos, GIIP0AI, dá entrada na emergência na 40ª semana de gestação em trabalho de parto. Relata perda de líquido há, aproximadamente, 40 minutos. Nega comorbidades ou qualquer outra queixa. Ao exame, verifica-se PA = 100 x 60 mmHg; AFU = 37 cm; BCF = 152 bpm; tônus uterino normal; metrossístoles 2/10’/40’’; colo em centralização, 100% apagado, cefálico, com 3 cm de dilatação e líquido claro com grumos.\n\nCom base no partograma do acompanhamento do trabalho de parto, mostrado a seguir, o diagnóstico é:","options":{"A":"Fase ativa prolongada.","B":"Período pélvico prolongado.","C":"Parada secundária da descida.","D":"Parada secundária da dilatação."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-dc516d64b3bcded6f6bcb29d104522b17ddb147f.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860821","ankiGuid":"L*&|_]7r+V"},{"id":"anki-obstetricia-partograma-e-distocia-795578953afa56fc","number":"0393l","sourceNumber":"0393l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Primigesta, com 39 semanas de gestação, foi internada e iniciado o acompanhamento com o partograma. Com base na figura abaixo, assinale a alternativa que corresponde ao período clínico e à variedade de posição fetal na última hora anotada.","options":{"A":"Primeiro período – occipito-direita-transversa.","B":"Primeiro período – occipito-esquerda-transversa.","C":"Segundo período – occipito-direita-transversa.","D":"Segundo período – occipito-esquerda-transversa.","E":"Terceiro período – occipito-direita-transversa."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-9d2500c0093871f717314e1b3d9247d8585a8057.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860822","ankiGuid":"gFNo<AP`u^"},{"id":"anki-obstetricia-partograma-e-distocia-407397f914692089","number":"0394l","sourceNumber":"0394l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Uma paciente primigesta com gestação a termo, concepto adequado para a idade gestacional e pré-natal sem intercorrências, é internada às 9 horas com duas contrações de 30 segundos em 10 minutos. Ao exame, o colo uterino está completamente apagado, médio na consistência e permeável para 3 cm de dilatação. Inicia-se a construção do partograma: apresentação cefálica; bolsa íntegra; 140 bpm de FCF; plano de DeLee -3. A avaliação das 14 horas mostrou colo fino central; permeável para 8 cm; plano de DeLee zero; traçado cardiotocográfico tranquilizador. Às 15 horas ocorreu a ruptura da bolsa com líquido meconial fluido e, às 16 horas, a dilatação do colo uterino está completa, plano de DeLee zero e 3 contrações em 10 minutos, durando 40 segundos. Às 17 e às 18 horas, observou-se a mesma condição anotada na avaliação das 16 horas, mas agora com bradicardia fetal durante as contrações. Qual o diagnóstico mais provável neste caso?","options":{"A":"Fase ativa prolongada.","B":"Hipocinesia uterina.","C":"Parada secundária da descida da apresentação.","D":"Parada secundária da progressão da dilatação."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860823","ankiGuid":"ME~mdn=Tca"},{"id":"anki-obstetricia-partograma-e-distocia-0795ce4e6f580167","number":"0395l","sourceNumber":"0395l","collectionBlock":"anki:obstetricia-partograma-e-distocia","collectionLabel":"Anki · Partograma e Distocia","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Partograma e Distocia","subtopic":"","stem":"Parturiente, 40 semanas e 2 dias, primigesta, pré-natal sem intercorrências. Ao exame físico: bom estado geral, afebril, normotensa, altura uterina = 34 cm; FCF = 140 bpm; rítmicos, sem desacelerações, na avaliação da bacia constata-se promontório inatingível, espinhas ciáticas médias, ângulo subpúbico de 90°. Apresenta evolução do trabalho de parto conforme o partograma:\n\nos diagnósticos constatados no partograma e a conduta nesse caso, respectivamente, são:","options":{"A":"Fase ativa prolongada e período expulsivo precipitado; ocitocina endovenosa e massagem perineal.","B":"Fase ativa protraída e período expulsivo prolongado; cesárea por desproporção feto pélvica relativa.","C":"Fase ativa prolongada e período pélvico prolongado; ocitocina endovenosa e posições verticalizadas.","D":"Fase ativa prolongada e período pélvico prolongado; aplicação do fórcipe de alívio.","E":"Parada secundária da dilatação e período expulsivo prolongado; ocitocina endovenosa."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Partograma e Distocia","images":["question_bank/media/obstetricia-partograma-e-distocia/paste-0ed4b4f7ee46bdf09a41c91b29bd5277bacc35d0.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Partograma e Distocia","Anki"],"ankiNoteId":"1779907860824","ankiGuid":"ogD+wJ$m*?"}]};
